(async () => {
  const fs = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const tsvMod = await import('node-tsv-json');
  const tsv = tsvMod.default || tsvMod;
  if (typeof tsv !== 'function') throw new Error('node-tsv-json export is not a function');
  const config = { input: globalThis.inputPath, output: globalThis.outputPath };
  const result = await new Promise((resolve, reject) => {
    tsv(config, (err, res) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
  globalThis.result = result;
})();

(async () => {
  const outputPath = globalThis.outputPath;
  if (!outputPath) throw new Error('output_path is undefined');
  console.log(JSON.stringify({ output_path: outputPath }));
})();
